query:
# Which of some usernames are members of a GitLab project whose member page (in
# gitlab-issues, gitlab-review-requests) has more. projectMembers filters by no username,
# only by a fuzzy search over username and name, so each username gets its own search.
# A template: every line holding the placeholder below is repeated once per username,
# the i-th copy with u<i> in its place; the username goes in variable u<i>.
query(
  $path: ID!
  $u0: String!
  $u1: String!
  $u2: String!
  $u3: String!
  $u4: String!
  $u5: String!
  $u6: String!
  $u7: String!
  $u8: String!
) {
  project(fullPath: $path) {
    u0: projectMembers(search: $u0, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u1: projectMembers(search: $u1, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u2: projectMembers(search: $u2, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u3: projectMembers(search: $u3, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u4: projectMembers(search: $u4, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u5: projectMembers(search: $u5, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u6: projectMembers(search: $u6, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u7: projectMembers(search: $u7, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
    u8: projectMembers(search: $u8, relations: [DIRECT, INHERITED, INVITED_GROUPS, SHARED_INTO_ANCESTORS], first: 100) { pageInfo { hasNextPage } nodes { user { username } } }
  }
}

